        if (q > stock) {
            throw new InsufficientStockException(id);
        }
        stock -= q;
    }

    public void restoreStock(int q) {
        if (q <= 0) {
            throw new IllegalArgumentException("Quantity must be positive");
        }
        stock += q;
    }
